    {date:"1890",title:"Eritrea colonia italiana",text:"La presenza italiana nel Mar Rosso diventa un possesso coloniale formalizzato.",scale:"Africa"},
    {date:"1891",title:"Transiberiana",text:"La grande ferrovia unisce modernizzazione economica, controllo territoriale e strategia asiatica russa.",scale:"Russia"},
    {date:"1894-1895",title:"Guerra sino-giapponese e caso Dreyfus",text:"Il Giappone emerge come potenza; la Francia entra in una crisi su esercito, diritti e antisemitismo.",scale:"Asia"},
    {date:"1896",title:"Adua e Madagascar",text:"L’Etiopia sconfigge l’Italia; la Francia trasforma il Madagascar in colonia.",scale:"Africa"},
    {date:"1898",title:"J’accuse e Fashoda",text:"Zola riapre il caso Dreyfus; Francia e Gran Bretagna arrivano vicino allo scontro in Sudan.",scale:"Imperi"},
    {date:"1899-1901",title:"Rivolta dei Boxer",text:"La coalizione internazionale reprime il movimento e impone nuove limitazioni alla Cina.",scale:"Asia"},
    {date:"1899-1902",title:"Seconda guerra anglo-boera",text:"Terra bruciata e campi di concentramento mostrano la violenza della guerra imperiale.",scale:"Africa"},
    {date:"1900",title:"Labour Representation Committee",text:"Sindacati e socialisti costruiscono una rappresentanza parlamentare comune.",scale:"Politica"},
    {date:"1904-1905",title:"Guerra russo-giapponese",text:"La vittoria giapponese rovescia il prestigio russo e spezza il mito dell’invincibilità europea.",scale:"Asia"},
    {date:"1905",title:"Portsmouth e rivoluzione russa",text:"La pace trasferisce diritti imperiali al Giappone; in Russia guerra e tensioni interne producono la rivoluzione.",scale:"Russia"},
    {date:"1906",title:"Dreyfus riabilitato e Labour Party",text:"La giustizia francese annulla la condanna; il nuovo partito britannico assume il nome definitivo.",scale:"Politica"}
